shaders.vertex:
#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
uniform 	mediump vec4 _Color;
in highp vec4 in_POSITION0;
in highp vec4 in_COLOR0;
in highp vec2 in_TEXCOORD0;
out mediump vec4 vs_COLOR0;
out mediump vec2 vs_TEXCOORD0;
out highp vec4 vs_TEXCOORD1;
vec4 u_xlat0;
vec4 u_xlat1;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    u_xlat0 = in_COLOR0 * _Color;
    vs_COLOR0 = u_xlat0;
    vs_TEXCOORD0.xy = in_TEXCOORD0.xy;
    vs_TEXCOORD1 = in_POSITION0;
    return;
}

shaders.fragment:
#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _Time;
uniform 	float _RgbCtrl;
uniform 	vec4 _ParticleTex_ST;
uniform 	float _DisturbUSpeed;
uniform 	float _DisturbVSpeed;
uniform 	vec4 _DisturbTex_ST;
uniform 	float _DisturbIntensity;
uniform 	float _DisturbModeCtrl;
uniform 	vec4 _DisturbMask_ST;
uniform 	vec4 _MainColor;
uniform 	float _DissolveSoftness;
uniform 	vec4 _DissolveMask_ST;
uniform 	float _DissolveMaskRotate;
uniform 	float _DissolveSpeedU;
uniform 	float _DissolveSpeedV;
uniform 	vec4 _DissolveTex_ST;
uniform 	float _DissolveIntensity;
uniform 	float _MainIntensity;
UNITY_LOCATION(0) uniform mediump sampler2D _DisturbTex;
UNITY_LOCATION(1) uniform mediump sampler2D _DisturbMask;
UNITY_LOCATION(2) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(3) uniform mediump sampler2D _ParticleTex;
UNITY_LOCATION(4) uniform mediump sampler2D _DissolveMask;
UNITY_LOCATION(5) uniform mediump sampler2D _DissolveTex;
in mediump vec4 vs_COLOR0;
in mediump vec2 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec2 u_xlat16_0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec3 u_xlat2;
mediump vec4 u_xlat16_2;
vec3 u_xlat3;
mediump vec2 u_xlat16_4;
vec2 u_xlat5;
mediump float u_xlat16_5;
vec2 u_xlat10;
mediump vec2 u_xlat16_10;
vec2 u_xlat11;
float u_xlat15;
mediump float u_xlat16_15;
void main()
{
    u_xlat0.xy = vs_TEXCOORD0.xy * _DissolveMask_ST.xy + _DissolveMask_ST.zw;
    u_xlat0.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat10.x = _DissolveMaskRotate * 0.0174532924;
    u_xlat1.x = sin(u_xlat10.x);
    u_xlat2.x = cos(u_xlat10.x);
    u_xlat3.z = u_xlat1.x;
    u_xlat3.y = u_xlat2.x;
    u_xlat3.x = (-u_xlat1.x);
    u_xlat1.y = dot(u_xlat0.xy, u_xlat3.xy);
    u_xlat1.x = dot(u_xlat0.xy, u_xlat3.yz);
    u_xlat0.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlat16_0.xy = texture(_DissolveMask, u_xlat0.xy).xw;
    u_xlat0.x = u_xlat16_0.y * u_xlat16_0.x;
    u_xlat5.xy = vs_TEXCOORD0.xy * _DisturbTex_ST.xy + _DisturbTex_ST.zw;
    u_xlat5.xy = _Time.yy * vec2(_DisturbUSpeed, _DisturbVSpeed) + u_xlat5.xy;
    u_xlat16_5 = texture(_DisturbTex, u_xlat5.xy).x;
    u_xlat5.x = u_xlat16_5 + -0.5;
    u_xlat5.x = u_xlat5.x + u_xlat5.x;
    u_xlat10.x = u_xlat5.x * _DisturbIntensity;
    u_xlat1.xy = vs_TEXCOORD0.xy * _DissolveTex_ST.xy + _DissolveTex_ST.zw;
    u_xlat10.xy = u_xlat10.xx * vec2(0.100000001, 0.100000001) + u_xlat1.xy;
    u_xlat1.xy = (-u_xlat10.xy) + vs_TEXCOORD0.xy;
    u_xlat10.xy = vec2(vec2(_DisturbModeCtrl, _DisturbModeCtrl)) * u_xlat1.xy + u_xlat10.xy;
    u_xlat10.xy = _Time.yy * vec2(_DissolveSpeedU, _DissolveSpeedV) + u_xlat10.xy;
    u_xlat16_10.xy = texture(_DissolveTex, u_xlat10.xy).xw;
    u_xlat10.x = u_xlat16_10.y * u_xlat16_10.x;
    u_xlat0.x = u_xlat10.x * u_xlat0.x;
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat10.x = _DissolveSoftness * 0.5;
    u_xlat15 = (-_DissolveSoftness) + 1.04999995;
    u_xlat16_4.xy = (-vs_COLOR0.xy) + vec2(1.0, 1.0);
    u_xlat1.x = (-u_xlat16_4.y) + _DissolveIntensity;
    u_xlat1.x = _RgbCtrl * u_xlat1.x + u_xlat16_4.y;
    u_xlat10.x = u_xlat1.x * u_xlat15 + u_xlat10.x;
    u_xlat10.x = u_xlat10.x * -1.04999995 + 0.549999952;
    u_xlat0.x = u_xlat10.x * 2.0 + u_xlat0.x;
    u_xlat0.x = u_xlat0.x + (-_DissolveSoftness);
    u_xlat10.x = _DissolveSoftness * -2.0 + 1.0;
    u_xlat10.x = float(1.0) / u_xlat10.x;
    u_xlat0.x = u_xlat10.x * u_xlat0.x;
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat10.x = u_xlat0.x * -2.0 + 3.0;
    u_xlat0.x = u_xlat0.x * u_xlat0.x;
    u_xlat0.x = u_xlat0.x * u_xlat10.x;
    u_xlat10.x = (-u_xlat16_4.x) + 1.0;
    u_xlat10.x = _RgbCtrl * u_xlat10.x + u_xlat16_4.x;
    u_xlat10.x = u_xlat10.x * _DisturbIntensity;
    u_xlat5.x = u_xlat5.x * u_xlat10.x;
    u_xlat5.xy = u_xlat5.xx * vec2(0.100000001, 0.100000001) + vs_TEXCOORD0.xy;
    u_xlat1.xy = vs_TEXCOORD0.xy * _ParticleTex_ST.xy + _ParticleTex_ST.zw;
    u_xlat5.xy = u_xlat5.xy + (-u_xlat1.xy);
    u_xlat11.xy = vs_TEXCOORD0.xy * _DisturbMask_ST.xy + _DisturbMask_ST.zw;
    u_xlat16_15 = texture(_DisturbMask, u_xlat11.xy).x;
    u_xlat5.xy = vec2(u_xlat16_15) * u_xlat5.xy + u_xlat1.xy;
    u_xlat16_1 = texture(_MainTex, u_xlat5.xy);
    u_xlat16_2 = texture(_ParticleTex, u_xlat5.xy);
    u_xlat1 = u_xlat16_1 * u_xlat16_2;
    u_xlat5.x = u_xlat1.w * vs_COLOR0.w;
    u_xlat5.x = u_xlat5.x * _MainColor.w;
    u_xlat0.w = u_xlat0.x * u_xlat5.x;
    u_xlat2.xyz = vs_COLOR0.xyz + vec3(-1.0, -1.0, -1.0);
    u_xlat2.xyz = vec3(_RgbCtrl) * u_xlat2.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = u_xlat1.xyz * u_xlat2.xyz;
    u_xlat0.xyz = u_xlat1.xyz * _MainColor.xyz;
    u_xlat0 = u_xlat0 * vec4(vec4(_MainIntensity, _MainIntensity, _MainIntensity, _MainIntensity));
    SV_Target0 = u_xlat0;
    return;
}

